,p_plug_display_sequence=>1
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_plug_source=>'<div class="faro-hero"><span class="faro-hero__icon fa fa-search" aria-hidden="true"></span><div><h1 class="faro-hero__title">Buscador de menciones</h1><p class="faro-hero__sub">Combine texto y filtros por canal, fecha, tema, pilar, sentimiento, vocero, institución y medio. Cada resultado enlaza a su evidencia.</p></div><div class="faro-hero__hu"><span class="faro-hu" title="Historia de usuario">TR-20</span><span class="faro-hu" title="Historia de usuario">TR-15</span></div></div>'
,p_plug_source_type=>'NATIVE_STATIC'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
