,p_plug_name=>'Encabezado'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3374665444246510938
,p_plug_display_sequence=>1
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_plug_source=>'<div class="faro-hero"><span class="faro-hero__icon fa fa-comments-o" aria-hidden="true"></span><div><h1 class="faro-hero__title">Asistente FARO</h1><p class="faro-hero__sub">Pregunte en lenguaje natural. Las respuestas usan sólo registros que usted está autorizado a ver y citan su evidencia.</p></div><div class="faro-hero__hu"><span class="faro-hu" title="Historia de usuario">TR-21</span></div></div>'
,p_plug_source_type=>'NATIVE_STATIC'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
