,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>' '
,p_query_no_data_found=>'<div class="faro-banner faro-banner--ia"><span class="fa fa-magic faro-banner__icon"></span><div>Empiece con una pregunta. Ejemplo: «¿Qué dijeron los congresistas sobre la autonomía del BCRP este mes?»</div></div>'
,p_query_num_rows_type=>'SHOW_ALL'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
