,p_plug_source=>'<div class="faro-hero"><span class="faro-hero__icon fa fa-sliders" aria-hidden="true"></span><div><h1 class="faro-hero__title">Criterios de monitoreo legislativo</h1><p class="faro-hero__sub">Términos ligados al catálogo común, escalas controladas de interés, prioridad, criticidad y nivel, con precedencia documentada.</p></div><div class="faro-hero__hu"><span class="faro-hu" title="Historia de usuario">EC-01</span><span class="faro-hu" title="Historia de usuario">EC-06</span></div></div>'
,p_plug_source_type=>'NATIVE_STATIC'
