,p_plug_name=>'Precedencia'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4504868307683981366
,p_plug_display_sequence=>5
,p_plug_display_point=>'BODY'
,p_plug_item_display_point=>'ABOVE'
,p_plug_source=>'<div class="faro-traza"><span><span class="fa fa-sort-numeric-asc"></span>Regla de precedencia: cuando varios criterios aplican, gana el de menor precedencia; a igualdad, el nivel más alto (N1 &gt; N2 &gt; N3 &gt; N4).</span><span><span class="fa fa-bullhorn"></span>N1 y N2: alerta inmediata · N3 y N4: reporte al término de la transmisión.</span></div>'
,p_plug_source_type=>'NATIVE_STATIC'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
