,p_plug_source=>'<div class="faro-hero"><span class="faro-hero__icon fa fa-key" aria-hidden="true"></span><div><h1 class="faro-hero__title">Permisos por módulo y capacidad</h1><p class="faro-hero__sub">Consulta, edición, validación, administración, indicadores, evidencias y permisos adicionales con vigencia.</p></div><div class="faro-hero__hu"><span class="faro-hu" title="Historia de usuario">TR-02</span><span class="faro-hu" title="Historia de usuario">TR-03</span></div></div>'
