wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(7300000018634)
,p_validation_name=>'Duplicados'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare l varchar2(4000);',
'begin',
'  if :REQUEST in (''CREAR'', ''GUARDAR'') and nvl(:P81_CONFIRMA, ''N'') = ''N'' then',
'    l := faro_cat.posibles_duplicados(''VOCERO'', :P81_NOMBRE, :P81_VOCERO_ID);',
'    if l is not null then',
'      :P81_DUPLICADOS := l;',
'      return ''Posibles duplicados o nombres equivalentes: '' || l || ''. Revise o confirme que no es un duplicado.'';',
'    end if;',
'  end if;',
'  return null;',
